The "stack depth limit exceeded" error is almost certainly caused by **infinite recursion in your Row-Level Security (RLS) policies**.

This happens when you have a circular dependency:
1.  The **`subjects`** table has a policy that checks **`subject_enrollments`** (e.g., "Students can see subjects they are enrolled in").
2.  The **`subject_enrollments`** table has a policy that checks **`subjects`** (e.g., "Teachers can see enrollments for their subjects").

When you try to enroll, the database checks the policies, which check each other endlessly until it crashes.

To fix this, we need to **break the loop** by using a "Security Definer" helper function for one of the policies. This function will check the database **bypassing RLS**, preventing the recursion.

**Run this SQL script in your Supabase SQL Editor:**

```sql
-- 1. Create a helper function to check teacher ownership securely (Bypasses RLS to break recursion)
CREATE OR REPLACE FUNCTION is_teacher_of_subject(lookup_subject_id bigint)
RETURNS boolean
LANGUAGE sql
SECURITY DEFINER -- This is crucial: it runs as superuser, ignoring the recursive policy on 'subjects'
STABLE
AS $$
  SELECT EXISTS (
    SELECT 1 FROM subjects 
    WHERE id = lookup_subject_id 
    AND teacher_id = auth.uid()
  );
$$;

-- 2. Drop the potentially recursive policies on subject_enrollments
DROP POLICY IF EXISTS "Teachers can manage enrollments" ON subject_enrollments;
DROP POLICY IF EXISTS "Teachers can view enrollments" ON subject_enrollments;
DROP POLICY IF EXISTS "Teacher manage enrollments" ON subject_enrollments;
DROP POLICY IF EXISTS "subject_enrollments_manage" ON subject_enrollments; 
-- (Dropping common names to be safe)

-- 3. Re-create the policy using the safe function
CREATE POLICY "Teachers can manage enrollments" 
ON subject_enrollments 
FOR ALL 
TO authenticated 
USING (
  is_teacher_of_subject(subject_id) 
  OR 
  auth.uid() = student_id -- Students can manage their own (insert/delete)
);

-- 4. Update the enroll_in_subject function to be extra safe
CREATE OR REPLACE FUNCTION enroll_in_subject(subject_code_to_enroll text)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public -- Best practice: prevents path hijacking
AS $$
DECLARE
  v_subject_id bigint;
  v_teacher_id uuid;
  v_student_id uuid;
  v_existing_status text;
  v_enrollment_id bigint;
BEGIN
  v_student_id := auth.uid();

  -- 1. Find the subject and teacher
  SELECT id, teacher_id INTO v_subject_id, v_teacher_id
  FROM subjects
  WHERE subject_code = subject_code_to_enroll;

  IF v_subject_id IS NULL THEN
    RETURN json_build_object('success', false, 'message', 'Invalid subject code.');
  END IF;

  -- 2. Check existing enrollment
  SELECT status INTO v_existing_status
  FROM subject_enrollments
  WHERE subject_id = v_subject_id AND student_id = v_student_id;

  IF v_existing_status IS NOT NULL THEN
    IF v_existing_status = 'pending' THEN
      RETURN json_build_object('success', false, 'message', 'You already have a pending request for this subject.');
    ELSIF v_existing_status = 'approved' THEN
      RETURN json_build_object('success', false, 'message', 'You are already enrolled in this subject.');
    ELSE
      RETURN json_build_object('success', false, 'message', 'You have already applied to this subject.');
    END IF;
  END IF;

  -- 3. Insert enrollment request
  INSERT INTO subject_enrollments (subject_id, student_id, status)
  VALUES (v_subject_id, v_student_id, 'pending')
  RETURNING id INTO v_enrollment_id;

  -- 4. Notify the teacher
  INSERT INTO notifications (
    recipient_id,
    actor_id,
    type,
    related_entity_id,
    related_subject_id
  )
  VALUES (
    v_teacher_id,
    v_student_id,
    'enrollment_request',
    v_enrollment_id,
    v_subject_id
  );

  RETURN json_build_object('success', true, 'message', 'Enrollment request sent to teacher.');
END;
$$;

