    AND (
      search_term IS NULL 
      OR p.full_name ILIKE '%' || search_term || '%' 
      OR au.email ILIKE '%' || search_term || '%'
    )
  ORDER BY p.created_at DESC
  LIMIT 50;
END;
$$;

DROP FUNCTION IF EXISTS admin_search_subjects(text) CASCADE;
CREATE OR REPLACE FUNCTION admin_search_subjects(search_term text)
RETURNS TABLE (
  id bigint,
  title text,
  subject_code text,
  teacher_name text,
  student_count bigint,
  created_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN QUERY
  SELECT 
    s.id,
    s.title,
    s.subject_code,
    p.full_name as teacher_name,
    (SELECT COUNT(*) FROM subject_enrollments se WHERE se.subject_id = s.id AND se.status = 'approved') as student_count,
    s.created_at
  FROM subjects s
  JOIN profiles p ON s.teacher_id = p.id
  WHERE 
    search_term IS NULL 
    OR s.title ILIKE '%' || search_term || '%' 
    OR s.subject_code ILIKE '%' || search_term || '%'
    OR p.full_name ILIKE '%' || search_term || '%'
  ORDER BY s.created_at DESC
  LIMIT 50;
END;
$$;

DROP FUNCTION IF EXISTS admin_delete_user(uuid) CASCADE;
CREATE OR REPLACE FUNCTION admin_delete_user(user_id_to_delete uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  DELETE FROM auth.users WHERE id = user_id_to_delete;
END;
$$;

DROP FUNCTION IF EXISTS admin_delete_subject(bigint) CASCADE;
CREATE OR REPLACE FUNCTION admin_delete_subject(subject_id_to_delete bigint)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  DELETE FROM subjects WHERE id = subject_id_to_delete;
END;
$$;

DROP FUNCTION IF EXISTS get_admin_stats() CASCADE;
CREATE OR REPLACE FUNCTION get_admin_stats()
RETURNS TABLE (
  total_users bigint,
  student_users bigint,
  teacher_users bigint,
  total_subjects bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  RETURN QUERY
  SELECT 
    (SELECT COUNT(*) FROM profiles),
    (SELECT COUNT(*) FROM profiles WHERE role = 'Student'),
    (SELECT COUNT(*) FROM profiles WHERE role = 'Teacher'),
    (SELECT COUNT(*) FROM subjects);
END;
$$;

DROP FUNCTION IF EXISTS get_admin_activity_trends() CASCADE;
CREATE OR REPLACE FUNCTION get_admin_activity_trends()
RETURNS TABLE (
  activity_date text,
  new_users bigint,
  study_sessions bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  RETURN QUERY
  WITH dates AS (
    -- Generate the last 7 days
    SELECT generate_series(
      CURRENT_DATE - INTERVAL '6 days',
      CURRENT_DATE,
      '1 day'::interval
    )::date AS day
  )
  SELECT 
    to_char(d.day, 'Mon DD') as activity_date,
    (SELECT COUNT(*) FROM profiles p WHERE p.created_at::date = d.day) as new_users,
    (SELECT COUNT(*) FROM study_sessions s WHERE s.completed_at::date = d.day) as study_sessions
  FROM dates d
  ORDER BY d.day ASC;
END;
$$;

-- 7. REPAIR CONSTRAINTS (Fix "Failed to create subject" due to dependency)
-- Drop the restrictive foreign key that requires a pre-existing code in subject_codes
ALTER TABLE subjects DROP CONSTRAINT IF EXISTS fk_subject_code_exists;

-- Ensure the generate function exists and is robust
CREATE OR REPLACE FUNCTION public.generate_subject_code()
RETURNS text
LANGUAGE sql
VOLATILE
AS $$
  -- Generate a random 8-character string (upper case hex)
  SELECT upper(substring(md5(random()::text) from 1 for 8));
$$;

ALTER TABLE subjects ALTER COLUMN subject_code SET DEFAULT generate_subject_code();

-- 8. RE-ENABLE RLS
ALTER TABLE subjects ENABLE ROW LEVEL SECURITY;
ALTER TABLE subject_enrollments ENABLE ROW LEVEL SECURITY;
ALTER TABLE subject_decks ENABLE ROW LEVEL SECURITY;
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;

-- 9. FORCE CACHE RELOAD
NOTIFY pgrst, 'reload config';

COMMIT;
`;

export const getErrorMessage = (error: unknown): string => {
    // 1. Handle explicit strings first.
    if (typeof error === 'string') {
        return error;
    }

    let message = '';

    // 2. Handle objects with a string 'message' property (most common for Supabase/API errors).
    if (error && typeof error === 'object' && 'message' in error && typeof (error as { message: unknown }).message === 'string') {
        message = (error as { message: string }).message;
    }
    // 3. Handle standard JavaScript Error objects.
    else if (error instanceof Error) {
        message = error.message;
    }

    // Translate common technical errors
    if (message.includes('duplicate key value violates unique constraint')) {
        return 'An item with this name or code already exists. Please choose a different one.';
    }
    if (message.includes('violates foreign key constraint')) {
         console.error("CRITICAL DATABASE ERROR: Foreign Key Constraint.");
         console.log("SQL FIX:\n", FIX_RECURSION_SQL);
         return 'DATABASE_RECURSION_ERROR: Database constraint violation (Foreign Key). This action failed due to a schema dependency issue. Please run the fixed SQL script in Supabase.';
    }
    if (message.includes('User not found')) {
        return 'No user was found with the provided credentials.';
    }
     if (message.includes('Invalid login credentials')) {
        return 'Invalid email or password. Please try again.';
    }
    if (message.includes('structure of query does not match function result type')) {
        return 'SCHEMA_CACHE_ERROR:The analytics function in the database has a data type mismatch. The app expected one format, but the database sent another. This requires a database update. Please ask your administrator to apply the latest SQL script for `get_subject_analytics`.';
    }
    if (message.includes('Could not choose the best candidate function')) {
        return 'SCHEMA_CACHE_ERROR:The database has conflicting function versions. Please run the updated SQL script in the Supabase editor to resolve this.';
    }
    if (message.includes('relation') && message.includes('does not exist')) {
         console.error("CRITICAL DATABASE ERROR: Missing Database Relation.");
         console.log("SQL FIX:\n", FIX_RECURSION_SQL);
         return 'DATABASE_RECURSION_ERROR: Missing database relations (tables/views). Please run the fixed SQL script in Supabase.';
    }
    if (message.includes('function') && message.includes('does not exist')) {
         console.error("CRITICAL DATABASE ERROR: Missing Database Function.");
         console.log("SQL FIX:\n", FIX_RECURSION_SQL);
         return 'DATABASE_RECURSION_ERROR: Missing database functions. Please run the fixed SQL script in Supabase.';
    }
    if (message.includes('column') && message.includes('does not exist')) {
         console.error("CRITICAL DATABASE ERROR: Schema mismatch (missing column).");
         console.log("SQL FIX:\n", FIX_RECURSION_SQL);
         return 'DATABASE_RECURSION_ERROR: Database schema mismatch (missing column). Please run the fixed SQL script in Supabase.';
    }
    if (message.includes('stack depth limit exceeded') || message.includes('infinite recursion')) {
        console.error("CRITICAL DATABASE ERROR: Infinite recursion in RLS policies detected.");
        console.log("SQL FIX:\n", FIX_RECURSION_SQL); // Log to console for easy access
        return 'DATABASE_RECURSION_ERROR: Infinite recursion detected in database policies. Please run the fixed SQL script in Supabase to resolve the RLS loop.';
    }
    // Supabase paused / Network issues
    if (message.includes('Failed to fetch') || message.includes('NetworkError') || message.includes('503')) {
        return 'Unable to connect to the server. The database might be paused due to inactivity. Please check the Supabase dashboard to restore the project.';
    }

    if (message) {
        return message;
    }

    // 4. As a fallback, try to stringify the entire error object.
    try {
        const str = JSON.stringify(error, null, 2); // Pretty-print for better debugging
        if (str !== '{}') {
            return str;
        }
    } catch {
        // Fall through to the final, safest fallback.
    }

    // 5. The ultimate fallback.
    try {
        return `[Unstructured Error]: ${String(error)}`;
    } catch {
        return 'An unknown and un-stringifiable error occurred.';
    }
};
